    # a gap in any projected line.
    blank_crosses = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and grid[r-1][c] == 3 and
                grid[r+1][c] == 3 and grid[r][c-1] == 3 and
                grid[r][c+1] == 3):
                blank_crosses.append((r, c))

    for r, c, color in centers:
        own_arms = {(r-1, c), (r+1, c), (r, c-1), (r, c+1)}
        # Project horizontally and vertically from the colored center.
        for dr, dc in ((0, 1), (0, -1), (1, 0), (-1, 0)):
            i, j = r + dr, c + dc
            while 0 <= i < h and 0 <= j < w:
                if grid[i][j] == 3 and (i, j) not in own_arms:
                    break
                if grid[i][j] != 3:
                    # A blank cross leaves a one-cell gap on its axis.
                    if not any((dc != 0 and j == bc) or
                               (dr != 0 and i == br)
                               for br, bc in blank_crosses):
                        out[i][j] = color
                i += dr
                j += dc

