def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]

    # A cross with four 3 arms and an empty center marks a gap in
    # horizontal projections at its column.
    blank_cols = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and grid[r-1][c] == 3 and
                grid[r+1][c] == 3 and grid[r][c-1] == 3 and
                grid[r][c+1] == 3):
                blank_cols.add(c)

    # Project each colored center in straight rays. Its own arms are
    # traversed; arms belonging to other crosses stop the ray.
    for r, c, color in centers:
        own_arms = {(r-1, c), (r+1, c), (r, c-1), (r, c+1)}
        for dr, dc in ((0, 1), (0, -1)):
            i, j = r + dr, c + dc
            while 0 <= i < h and 0 <= j < w:
                if grid[i][j] == 3 and (i, j) not in own_arms:
                    break
                if grid[i][j] != 3 and j not in blank_cols:
                    out[i][j] = color
                i += dr
                j += dc

    for r, c, color in centers:
        own_arms = {(r-1, c), (r+1, c), (r, c-1), (r, c+1)}
        for dr, dc in ((1, 0), (-1, 0)):
            i, j = r + dr, c + dc
            while 0 <= i < h and 0 <= j < w:
                if grid[i][j] == 3 and (i, j) not in own_arms:
                    break
                if grid[i][j] != 3:
                    out[i][j] = color
                i += dr
                j += dc

    return out
